/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* Designme shared core: tokens for Blueprint (default) and Soft (data-style="soft" on <html> or on any element around the components), light and dark (<html data-theme="dark">) */
:where([data-dm]) [hidden]{display:none!important}
/* hold(): an end state centred in the height its component had */
.dm-held{display:flex;flex-direction:column;justify-content:center}
/* the glide starts fast in both styles, so the field is on its way up before an opening list reaches the stage's edge */
.dm-glide{transform:translateY(var(--dm-gy,0px));transition:transform var(--dm-t) cubic-bezier(.22,1,.36,1)}
/* and a list that opens under a gliding field fades in a beat after it starts to move */
.dm-glide>.dm-csx-pop.dm-open{transition-delay:.08s}
.dm-glide>.dm-msc-pop.dm-open{transition-delay:.08s,.08s,.08s,0s}
/* Soft 2: one quiet surface per object, grey type for finished work, motion only on what is happening now */
:root,[data-style="soft"]{
  --dm-motion:soft;
  --dm-page:#f7f7f7; --dm-stage:#fafafa; --dm-surface:#ffffff; --dm-raised:#ffffff;
  --dm-fg:#171717; --dm-fg2:#525252; --dm-muted:#6a6a6a; --dm-faint:#c4c4c4; --dm-rail:#d4d4d4; --dm-line:#e8e8e8; --dm-field-line:#d4d4d4; --dm-line-strong:#858585; --dm-field-line-strong:#b3b3b3;
  --dm-chip:#f3f3f3; --dm-hover:#ebebeb; --dm-press:#e3e3e3; --dm-wash:#f9f9f9; --dm-row:#fafafa;
  --dm-soft:#ececec; --dm-soft-h:#e3e3e3; --dm-soft-ring:inset 0 0 0 1px rgba(0,0,0,.03); --dm-dis:#a6a6a6;
  /* disabled: text and icons take --dis; a control with a fill swaps it for --dis-fill (Blueprint hatches it) */
  --dm-dis-fill:var(--dm-soft); --dm-dis-hatch:none;
  --dm-shadow-lift:0 0 0 1px rgba(0,0,0,.05),0 2px 4px rgba(0,0,0,.04),0 16px 32px -10px rgba(0,0,0,.16);
  /* the accent has three roles: --accent fills (with --on-accent on top, 4.5:1), --accent-fg is text and icons in the accent
     (4.5:1 on the surface, and on the chips and tints it sits on) and --accent-mark is lines, rings and chart marks (3:1). A
     light accent like lime keeps its fills and gets a darker mark and ink-coloured text on a light page */
  --dm-accent:#116ff8; --dm-on-accent:#ffffff; --dm-accent-fg:#0f5fd5; --dm-accent-mark:#116ff8; --dm-sel:color-mix(in srgb,var(--dm-accent) 6%,transparent);
  /* fields (text fields, textareas, search fields, dropdown triggers) have a dimmed grey edge, --field-line, that steps up
     a little, to --field-line-strong, while they have the focus. The keyboard's focus ring on every other control is 2px of
     a stronger grey (--line-strong, as --focus), as an outline offset 2px, or as a 2px box-shadow ring where an outline would be clipped. Never
     the accent and never black, and only from the keyboard (:focus-visible), so a click or a tap never shows one */
  --dm-focus:var(--dm-line-strong);
  --dm-ink:#1b1b1b; --dm-on-ink:#ffffff;
  --dm-ok:#137739; --dm-ok-bg:#e8f6ee; --dm-warn:#a94e09; --dm-warn-bg:#fdf3df; --dm-bad:#bf3434; --dm-bad-bg:#fdecec;
  --dm-merge:#7c4cd4; --dm-merge-bg:#f2ecfd; --dm-add:#187633; --dm-del:#c7212c;
  --dm-pb:#1460d0; --dm-pb-bg:#eaf2ff; --dm-pl:#6b47d6; --dm-pl-bg:#f2edff; --dm-pm:#10754a; --dm-pm-bg:#e7f8f0; --dm-pp:#994c0b; --dm-pp-bg:#fff2e6;
  --dm-pr:#bf314d; --dm-pr-bg:#ffeef1; --dm-py:#856404; --dm-py-bg:#fffae3; --dm-pk:#b92e75; --dm-pk-bg:#fff0f7; --dm-pt:#0e747d; --dm-pt-bg:#e6f9fa;
  /* avatars have colours of their own, the same in every style and theme: a bright fill and the initials' ink on it (4.5:1,
     APCA Lc 60). Blue, violet, red and pink are deep enough for white; green, teal, yellow and orange are too light for white
     and take a dark ink of their own hue. An avatar given one of these, var(--av-l), takes its ink, var(--av-l-ink), on its own */
  --dm-av-b:#126fe6; --dm-av-b-ink:#ffffff; --dm-av-l:#834ff5; --dm-av-l-ink:#ffffff; --dm-av-r:#d73341; --dm-av-r-ink:#ffffff; --dm-av-k:#cf3288; --dm-av-k-ink:#ffffff;
  --dm-av-m:#27cf86; --dm-av-m-ink:#052616; --dm-av-t:#28c9d8; --dm-av-t-ink:#042428; --dm-av-y:#e9ac1a; --dm-av-y-ink:#2a1d03; --dm-av-p:#fda154; --dm-av-p-ink:#301804;
  --dm-ts:#2c6cb2; --dm-react:#0a738b;
  /* every raised surface carries its own hairline edge, so nothing needs a separate ring */
  --dm-shadow:0 0 0 1px rgba(0,0,0,.035),0 1px 2px rgba(0,0,0,.04),0 8px 16px -8px rgba(0,0,0,.08);
  --dm-shadow-pop:0 0 0 1px rgba(0,0,0,.04),0 1px 1px rgba(0,0,0,.02),0 4px 8px -4px rgba(0,0,0,.04),0 16px 24px -8px rgba(0,0,0,.06);
  --dm-shadow-toast:0 0 0 1px rgba(0,0,0,.03),0 4px 12px rgba(0,0,0,.08);
  --dm-hl:#fdeb9a; --dm-hl-ok:#d3f1df;
  --dm-r-card:16px;
  /* spacing runs on a 4px scale, and corners on a small set of radii; values off the scale are still written out */
  --dm-s-1:4px; --dm-s-2:8px; --dm-s-3:12px; --dm-s-4:16px; --dm-s-5:20px; --dm-s-6:24px; --dm-s-8:32px; --dm-r-xs:4px; --dm-r-lg:20px; --dm-r-in:12px; --dm-r-sm:8px; --dm-r-pill:999px;
  /* fields and tags have slightly rounded corners, never pills: --r-field for one-line fields and dropdown triggers, --r-box
     for boxes you write several lines in, --r-tag for tags. Where the browser smooths corners (corner-shape: squircle) a
     corner looks smaller, so each takes the larger -sq radius there to look the same size. Fields share one height and,
     where a component is a single field, one width */
  --dm-r-field:var(--dm-r-sm); --dm-r-field-sq:14px; --dm-r-box:var(--dm-r-in); --dm-r-box-sq:20px; --dm-r-tag:6px; --dm-r-tag-sq:10px;
  --dm-field-h:40px; --dm-field-w:320px;
  --dm-sans:"Inter",ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;
  --dm-mono:"JetBrains Mono",ui-monospace,SFMono-Regular,Menlo,monospace;
  --dm-ease:cubic-bezier(.22,1,.36,1); --dm-ease-io:cubic-bezier(.65,0,.35,1);
  --dm-t-fast:.22s; --dm-t:.45s; --dm-t-slow:.7s;
}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]),:root:not([data-theme="light"]) [data-style="soft"]{
  --dm-page:#111111; --dm-stage:#1c1c1c; --dm-surface:#262626; --dm-raised:#2c2c2c;
  --dm-fg:#f2f2f2; --dm-fg2:#c9c9c9; --dm-muted:#c0c0c0; --dm-faint:#555555; --dm-rail:#414141; --dm-line:#333333; --dm-field-line:#424242; --dm-line-strong:#808080; --dm-field-line-strong:#808080;
  --dm-chip:#303030; --dm-hover:#373737; --dm-press:#3f3f3f; --dm-wash:#2c2c2c; --dm-row:color-mix(in srgb,var(--dm-fg) 5.5%,transparent);
  --dm-soft:#323232; --dm-soft-h:#3a3a3a; --dm-soft-ring:inset 0 0 0 1px rgba(255,255,255,.035); --dm-dis:#737373;
  --dm-shadow-lift:0 0 0 1px rgba(255,255,255,.08),0 2px 4px rgba(0,0,0,.3),0 16px 32px -10px rgba(0,0,0,.6);
  --dm-accent:#116ff8; --dm-on-accent:#ffffff; --dm-accent-fg:#9dc4ff; --dm-accent-mark:#3d8bff; --dm-sel:color-mix(in srgb,var(--dm-accent) 9%,transparent);
  --dm-ink:#f2f2f2; --dm-on-ink:#161616;
  --dm-ok:#63d998; --dm-ok-bg:rgba(60,207,126,.13); --dm-warn:#f1bb4e; --dm-warn-bg:rgba(240,180,60,.13); --dm-bad:#ffabab; --dm-bad-bg:rgba(255,107,107,.13);
  --dm-merge:#cbb8ff; --dm-merge-bg:rgba(169,139,255,.15); --dm-add:#63d998; --dm-del:#ffa9ae;
  --dm-pb:#a0c5ff; --dm-pb-bg:rgba(90,150,255,.18); --dm-pl:#cbb9ff; --dm-pl-bg:rgba(155,125,255,.18); --dm-pm:#6ad9a7; --dm-pm-bg:rgba(70,205,150,.16); --dm-pp:#ffb57a; --dm-pp-bg:rgba(255,155,80,.17);
  --dm-pr:#ffadbb; --dm-pr-bg:rgba(255,105,130,.17); --dm-py:#f0cd5a; --dm-py-bg:rgba(240,200,60,.15); --dm-pk:#ffa8d4; --dm-pk-bg:rgba(255,100,175,.16); --dm-pt:#5fd8df; --dm-pt-bg:rgba(60,200,210,.16);
  --dm-ts:#8fbcff; --dm-react:#3dd0ee;
  --dm-shadow:0 0 0 1px rgba(255,255,255,.04),0 1px 2px rgba(0,0,0,.3),0 8px 16px -8px rgba(0,0,0,.4); --dm-shadow-pop:0 0 0 1px rgba(255,255,255,.05),0 4px 8px -4px rgba(0,0,0,.4),0 16px 32px -8px rgba(0,0,0,.5); --dm-shadow-toast:0 0 0 1px rgba(255,255,255,.05),0 4px 12px rgba(0,0,0,.4); --dm-hl:rgba(240,200,60,.3); --dm-hl-ok:rgba(60,207,126,.24); color-scheme:dark}}
:root[data-theme="dark"],:root[data-theme="dark"] [data-style="soft"]{
  --dm-page:#111111; --dm-stage:#1c1c1c; --dm-surface:#262626; --dm-raised:#2c2c2c;
  --dm-fg:#f2f2f2; --dm-fg2:#c9c9c9; --dm-muted:#c0c0c0; --dm-faint:#555555; --dm-rail:#414141; --dm-line:#333333; --dm-field-line:#424242; --dm-line-strong:#808080; --dm-field-line-strong:#808080;
  --dm-chip:#303030; --dm-hover:#373737; --dm-press:#3f3f3f; --dm-wash:#2c2c2c; --dm-row:color-mix(in srgb,var(--dm-fg) 5.5%,transparent);
  --dm-soft:#323232; --dm-soft-h:#3a3a3a; --dm-soft-ring:inset 0 0 0 1px rgba(255,255,255,.035); --dm-dis:#737373;
  --dm-shadow-lift:0 0 0 1px rgba(255,255,255,.08),0 2px 4px rgba(0,0,0,.3),0 16px 32px -10px rgba(0,0,0,.6);
  --dm-accent:#116ff8; --dm-on-accent:#ffffff; --dm-accent-fg:#9dc4ff; --dm-accent-mark:#3d8bff; --dm-sel:color-mix(in srgb,var(--dm-accent) 9%,transparent);
  --dm-ink:#f2f2f2; --dm-on-ink:#161616;
  --dm-ok:#63d998; --dm-ok-bg:rgba(60,207,126,.13); --dm-warn:#f1bb4e; --dm-warn-bg:rgba(240,180,60,.13); --dm-bad:#ffabab; --dm-bad-bg:rgba(255,107,107,.13);
  --dm-merge:#cbb8ff; --dm-merge-bg:rgba(169,139,255,.15); --dm-add:#63d998; --dm-del:#ffa9ae;
  --dm-pb:#a0c5ff; --dm-pb-bg:rgba(90,150,255,.18); --dm-pl:#cbb9ff; --dm-pl-bg:rgba(155,125,255,.18); --dm-pm:#6ad9a7; --dm-pm-bg:rgba(70,205,150,.16); --dm-pp:#ffb57a; --dm-pp-bg:rgba(255,155,80,.17);
  --dm-pr:#ffadbb; --dm-pr-bg:rgba(255,105,130,.17); --dm-py:#f0cd5a; --dm-py-bg:rgba(240,200,60,.15); --dm-pk:#ffa8d4; --dm-pk-bg:rgba(255,100,175,.16); --dm-pt:#5fd8df; --dm-pt-bg:rgba(60,200,210,.16);
  --dm-ts:#8fbcff; --dm-react:#3dd0ee;
  --dm-shadow:0 0 0 1px rgba(255,255,255,.04),0 1px 2px rgba(0,0,0,.3),0 8px 16px -8px rgba(0,0,0,.4); --dm-shadow-pop:0 0 0 1px rgba(255,255,255,.05),0 4px 8px -4px rgba(0,0,0,.4),0 16px 32px -8px rgba(0,0,0,.5); --dm-shadow-toast:0 0 0 1px rgba(255,255,255,.05),0 4px 12px rgba(0,0,0,.4); --dm-hl:rgba(240,200,60,.3); --dm-hl-ok:rgba(60,207,126,.24); color-scheme:dark}

/* the accent's hover fill (--accent-2) and tint (--accent-bg) are worked out from the accent, in every style and theme, so a
   picked accent brings its own. Hovering a filled button moves its fill away from its text colour: darker under white text,
   lighter under dark text, so the label keeps its contrast in every style, theme and accent */
:root,[data-style="soft"]{--dm-accent-2:color-mix(in srgb,var(--dm-accent) 86%,#000);--dm-accent-bg:color-mix(in srgb,var(--dm-accent) 9%,transparent)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]),:root:not([data-theme="light"]) [data-style="soft"]{--dm-accent-2:color-mix(in srgb,var(--dm-accent) 84%,#fff);--dm-accent-bg:color-mix(in srgb,var(--dm-accent) 13%,transparent)}}
:root[data-theme="dark"],:root[data-theme="dark"] [data-style="soft"]{--dm-accent-2:color-mix(in srgb,var(--dm-accent) 84%,#fff);--dm-accent-bg:color-mix(in srgb,var(--dm-accent) 13%,transparent)}
@supports (color:rgb(from red r g b)){:root,[data-style="soft"],:root:not([data-theme="light"]),:root:not([data-theme="light"]) [data-style="soft"],:root[data-theme="dark"],:root[data-theme="dark"] [data-style="soft"]{--dm-accent-2:color-mix(in srgb,var(--dm-accent) 86%,rgb(from var(--dm-on-accent) calc(255 - r) calc(255 - g) calc(255 - b)))}}
@supports not (color:rgb(from red r g b)){:root,[data-style="soft"],:root:not([data-theme="light"]),:root:not([data-theme="light"]) [data-style="soft"],:root[data-theme="dark"],:root[data-theme="dark"] [data-style="soft"]{--dm-accent-2:color-mix(in srgb,var(--dm-accent) 86%,#000)}:root:not([data-style="soft"]),:root:not([data-style="soft"]):not([data-theme="light"]),:root:not([data-style="soft"])[data-theme="dark"]{--dm-accent-2:color-mix(in srgb,var(--dm-accent) 86%,#fff)}}
/* picked things (chips, options, cards in a picker) are white tiles with a dimmed grey edge, and the picked one's edge
   is a light step stronger, never a dark or black outline */
:root,[data-style="soft"]{--dm-pick-line:var(--dm-rail);--dm-pick-on:var(--dm-faint)}

/* ---------- page shell ---------- */
:where([data-dm]) *{box-sizing:border-box}
:where([data-dm]) button,:where([data-dm]) input,:where([data-dm]) textarea,:where([data-dm]) select{font:inherit;color:inherit}
:where([data-dm]) button{background:none;border:0;padding:0;cursor:pointer}
/* one weight for emphasis: medium, never bold */
:where([data-dm]) b,:where([data-dm]) strong{font-weight:500}
:where([data-dm]) :focus-visible{outline:2px solid var(--dm-focus);outline-offset:2px;border-radius:6px}
/* a field shows the focus with its own edge, which steps up to --field-line-strong, so it never takes the ring as well */
:where([data-dm]) :focus-visible:is(input:not([type="checkbox"],[type="radio"],[type="range"],[type="file"],[type="button"],[type="submit"],[type="reset"]),textarea,select,[contenteditable]:not([contenteditable="false"])){outline:0}/* ---------- icons ---------- */
.dm-i{width:16px;height:16px;flex:none;display:inline-block;vertical-align:-3px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.dm-i.dm-s{width:14px;height:14px}.dm-i.dm-xs{width:12px;height:12px}.dm-i.dm-l{width:18px;height:18px}
.dm-brand{width:16px;height:16px;display:block;flex:none}
.dm-flag{width:20px;height:15px;border-radius:3px;object-fit:cover;display:block;flex:none;box-shadow:0 0 0 1px rgba(0,0,0,.08)}

/* ---------- primitives ---------- */
.dm-mono{font-family:var(--dm-mono)}
.dm-sp{flex:1}
.dm-num{font-variant-numeric:tabular-nums}
.dm-muted{color:var(--dm-muted)}.dm-fg2{color:var(--dm-fg2)}
.dm-panel{background:var(--dm-surface);border-radius:var(--dm-r-card);box-shadow:var(--dm-shadow);position:relative}
.dm-ib{width:30px;height:30px;border-radius:50%;display:inline-grid;place-items:center;color:var(--dm-fg2);transition:background var(--dm-t-fast),color var(--dm-t-fast),transform .15s}
@media (hover:hover) and (pointer:fine){.dm-ib:hover{background:var(--dm-row);color:var(--dm-fg)}}
.dm-ib:active{transform:scale(.94)}
.dm-ib.dm-fill{background:var(--dm-soft);box-shadow:var(--dm-soft-ring)}
@media (hover:hover) and (pointer:fine){.dm-ib.dm-fill:hover{background:var(--dm-soft-h)}}
.dm-ib.dm-on{background:var(--dm-accent-bg);color:var(--dm-accent-fg,var(--dm-accent))}
.dm-chip{display:inline-flex;align-items:center;gap:6px;height:30px;padding:0 var(--dm-s-3);border-radius:var(--dm-r-pill);font-size:13px;color:var(--dm-fg2);background:var(--dm-chip);white-space:nowrap;transition:background var(--dm-t-fast),color var(--dm-t-fast),box-shadow var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.dm-chip:hover{background:var(--dm-hover);color:var(--dm-fg)}}
.dm-chip.dm-on{background:var(--dm-surface);color:var(--dm-fg);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-on) 50%,transparent)}
.dm-chip.dm-sm{height:24px;padding:0 9px;font-size:12px}
.dm-pill{display:inline-flex;align-items:center;justify-content:center;gap:7px;height:32px;padding:0 14px;border-radius:var(--dm-r-pill);font-size:13px;font-weight:500;white-space:nowrap;transition:background var(--dm-t-fast),color var(--dm-t-fast),opacity var(--dm-t-fast),transform .15s}
.dm-pill:active{transform:scale(.97)}
/* the primary action is the accent, with --on-accent on it, so it follows the accent and stays readable in any colour */
.dm-pill.dm-primary{background:var(--dm-accent);color:var(--dm-on-accent)}
@media (hover:hover) and (pointer:fine){.dm-pill.dm-primary:hover{background:var(--dm-accent-2)}}
.dm-pill.dm-accent{background:var(--dm-accent);color:var(--dm-on-accent)}
.dm-pill.dm-accent.dm-hl{background:var(--dm-accent-2)}
@media (hover:hover) and (pointer:fine){.dm-pill.dm-accent:hover{background:var(--dm-accent-2)}}
.dm-pill.dm-soft{background:var(--dm-soft);color:var(--dm-fg);box-shadow:var(--dm-soft-ring)}
@media (hover:hover) and (pointer:fine){.dm-pill.dm-soft:hover{background:var(--dm-soft-h)}}
.dm-pill.dm-line{background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);color:var(--dm-fg)}
.dm-pill.dm-ghost{color:var(--dm-fg2)}@media (hover:hover) and (pointer:fine){.dm-pill.dm-ghost:hover{background:var(--dm-row);color:var(--dm-fg)}}
/* one disabled look for every control: nothing fades; its text and icons take --dis, a control with a fill swaps the fill
   for --dis-fill with its quiet edge (hatched in Blueprint), one without keeps no fill, and the pointer says not-allowed */
.dm-pill[disabled]{opacity:1;color:var(--dm-dis);background:none;cursor:not-allowed;transform:none}
@media (hover:hover) and (pointer:fine){.dm-pill[disabled]:hover{opacity:1;color:var(--dm-dis);background:none;cursor:not-allowed;transform:none}}
:where([data-dm]) button:disabled{cursor:not-allowed}
.dm-pill:is(.dm-accent,.dm-primary,.dm-soft,.dm-line)[disabled]{background:var(--dm-dis-hatch),var(--dm-dis-fill);color:var(--dm-dis);box-shadow:var(--dm-soft-ring)}
@media (hover:hover) and (pointer:fine){.dm-pill:is(.dm-accent,.dm-primary,.dm-soft,.dm-line)[disabled]:hover{background:var(--dm-dis-hatch),var(--dm-dis-fill);color:var(--dm-dis);box-shadow:var(--dm-soft-ring)}}
.dm-pill[disabled] .dm-kbd{background:var(--dm-chip);color:inherit}
.dm-pill.dm-sm{height:28px;padding:0 11px;font-size:12.5px}
.dm-tag{display:inline-flex;align-items:center;gap:5px;height:20px;padding:0 7px;border-radius:var(--dm-r-tag);font-size:11.5px;font-weight:500;white-space:nowrap;background:var(--dm-chip);color:var(--dm-fg2)}
.dm-tag.dm-b{background:var(--dm-pb-bg);color:var(--dm-pb)}.dm-tag.dm-l{background:var(--dm-pl-bg);color:var(--dm-pl)}.dm-tag.dm-m{background:var(--dm-pm-bg);color:var(--dm-pm)}.dm-tag.dm-p{background:var(--dm-pp-bg);color:var(--dm-pp)}
.dm-tag.dm-r{background:var(--dm-pr-bg);color:var(--dm-pr)}.dm-tag.dm-y{background:var(--dm-py-bg);color:var(--dm-py)}.dm-tag.dm-k{background:var(--dm-pk-bg);color:var(--dm-pk)}.dm-tag.dm-t{background:var(--dm-pt-bg);color:var(--dm-pt)}
.dm-tag.dm-ok{background:var(--dm-ok-bg);color:var(--dm-ok)}.dm-tag.dm-warn{background:var(--dm-warn-bg);color:var(--dm-warn)}.dm-tag.dm-bad{background:var(--dm-bad-bg);color:var(--dm-bad)}
@supports (corner-shape:squircle){.dm-tag{corner-shape:squircle;border-radius:var(--dm-r-tag-sq)}}
.dm-dot{width:6px;height:6px;border-radius:50%;background:currentColor;flex:none;display:inline-block}
.dm-fchip{display:inline-flex;align-items:center;gap:6px;height:26px;padding:0 10px 0 var(--dm-s-2);border-radius:var(--dm-r-pill);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:12.5px;color:var(--dm-fg);white-space:nowrap}
.dm-fchip.dm-lnk{cursor:pointer;transition:background var(--dm-t-fast),box-shadow var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.dm-fchip.dm-lnk:hover{background:var(--dm-row);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 50%,transparent)}}
