}

/** State that can be controlled by the parent (value + onChange) or left to the component (defaultValue) */
export function useControllable<T>(value: T | undefined, defaultValue: T, onChange?: (v: T) => void) {
  const [inner, setInner] = useState(defaultValue);
  const controlled = value !== undefined;
  const set = useCallback((v: T) => { if (!controlled) setInner(v); onChange?.(v); }, [controlled, onChange]);
  return [controlled ? value : inner, set] as const;
}

/** Copies text to the clipboard and stays true for `ms`, long enough to show a check mark and a "Copied" tip */
export function useCopied(ms = 1600) {
  const [copied, setCopied] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  useEffect(() => () => clearTimeout(timer.current), []);
  const copy = useCallback((text: string) => {
    try { navigator.clipboard?.writeText(text).catch(() => {}); } catch { /* the page is not allowed to write to the clipboard */ }
    setCopied(true); clearTimeout(timer.current);
    timer.current = setTimeout(() => setCopied(false), ms);
  }, [ms]);
  return [copied, copy] as const;
}

'use client';
import { cloneElement, isValidElement, useEffect, useRef, useState, type CSSProperties, type FocusEvent, type PointerEvent, type ReactNode, type Ref, type RefObject } from 'react';
import { createPortal } from 'react-dom';
import { cx } from './cx';
import { useIsoLayoutEffect, useReducedMotion } from './hooks';
import { Icon } from './icons';

/* ---------- status glyphs ---------- */
/** Four dots turning: the agent is thinking */
export const Think = ({ on = true, className }: { on?: boolean; className?: string }) => (
  <span className={cx('dm-think', on && 'dm-on', className)} aria-hidden="true"><i /><i /><i /><i /></span>
);
/** A ring spinning: work in progress */
export const Spin = () => <span className="dm-spin" aria-hidden="true" />;
/** A dot with a sweeping ring: reading or searching */
export const Radar = () => <span className="dm-radar" aria-hidden="true" />;
/** A grey dot with a soft ping: the step happening now */
export const Pulse = () => <span className="dm-pulse" aria-hidden="true" />;
/** Three bars rising and falling */
export const Bars = () => <span className="dm-bars3" aria-hidden="true"><i /><i /><i /></span>;
/** A small round dot, coloured by `color` (or currentColor) */
export const Dot = ({ color }: { color?: string }) => <span className="dm-dot" style={color ? { color } : undefined} aria-hidden="true" />;

/* ---------- text that changes ---------- */
/** Text that blurs out and back in when it changes */
export function Swap({ children, className, style }: { children: string; className?: string; style?: CSSProperties }) {
  const [shown, setShown] = useState(children);
  const [out, setOut] = useState(false);
  const reduce = useReducedMotion();
  useEffect(() => {
    if (children === shown) { setOut(false); return; }
    setOut(true);
    const t = setTimeout(() => { setShown(children); setOut(false); }, reduce ? 0 : 170);
    return () => clearTimeout(t);
  }, [children, shown, reduce]);
  return <span className={cx('dm-sw', out && 'dm-out', className)} style={style}>{shown}</span>;
}

/* ---------- layout ---------- */
/** A panel that folds open and shut by its height */
export function Fold({ open, className, children }: { open: boolean; className?: string; children: ReactNode }) {
  return <div className={cx('dm-fold', !open && 'dm-shut', className)} inert={!open} aria-hidden={!open}><div>{children}</div></div>;
}

/** Segmented control with a sliding knob */
export function Seg<T extends string>({ options, value, onChange, label, className }: {
  // T comes from value, so options and onChange are checked against it rather than widening it
  options: { value: NoInfer<T>; label: ReactNode }[]; value: T; onChange: (v: NoInfer<T>) => void; label: string; className?: string;
}) {
  const ref = useRef<HTMLDivElement>(null);
  const [knob, setKnob] = useState<CSSProperties>({});
  useIsoLayoutEffect(() => {
    const el = ref.current; if (!el) return;
    const place = () => { const b = el.querySelector<HTMLElement>('[aria-pressed="true"]'); if (b) setKnob({ left: b.offsetLeft, width: b.offsetWidth }); };
    place();
    const ro = new ResizeObserver(place); ro.observe(el);
    return () => ro.disconnect();
  }, [value, options.length]);
  return (
    <div className={cx('dm-seg2', className)} role="group" aria-label={label} ref={ref}>
      <span className="dm-knob" style={knob} />
      {options.map(o => <button type="button" key={o.value} aria-pressed={o.value === value} onClick={() => onChange(o.value)}>{o.label}</button>)}
    </div>
  );
}

/* ---------- tooltip ---------- */
// when the last visible tip closed, shared by every Tip on the page
let tipSeen = -Infinity;
type Handlers = { onPointerEnter?: (e: PointerEvent) => void; onPointerLeave?: (e: PointerEvent) => void; onFocus?: (e: FocusEvent) => void; onBlur?: (e: FocusEvent) => void; ref?: Ref<Element> };
const setRef = (ref: Ref<Element> | undefined, node: Element | null) => { if (typeof ref === 'function') ref(node); else if (ref) (ref as RefObject<Element | null>).current = node; };

/** Shows `label` above the element it wraps, after a short pause, the same way the site does.
    `kbd` adds a shortcut after the label, `open` shows it straight away (for feedback like "Copied"),
    and `off` keeps it hidden, for example while the button's own menu is open.
    A single HTML element is used as is, so the tip adds nothing to the layout; anything else gets a display:contents wrapper. */
export function Tip({ label, kbd, open: forced, off, side = 'top', children }: { label: string; kbd?: string; open?: boolean; off?: boolean; side?: 'top' | 'bottom'; children: ReactNode }) {
  const [at, setAt] = useState<{ x: number; y: number; r: DOMRect } | null>(null);
  const [show, setShow] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  const tip = useRef<HTMLDivElement>(null);
  const target = useRef<Element | null>(null);
  // whether the pointer is on the target: a tip opened from code and then let go stays while the pointer is on it
  const over = useRef(false);
  const open = (el: Element | null | undefined, now = false) => {
    if (!el) return; clearTimeout(timer.current);
    // moving straight from one tip to the next shows it at once, as on the site
    timer.current = setTimeout(() => setAt({ x: 0, y: 0, r: el.getBoundingClientRect() }), now || performance.now() - tipSeen < 120 ? 0 : 380);
  };
  const close = () => { clearTimeout(timer.current); if (tip.current) tipSeen = performance.now(); setShow(false); setAt(null); };
  useEffect(() => () => clearTimeout(timer.current), []);
  useEffect(() => { if (forced) open(target.current, true); else if (!over.current) close(); }, [forced]); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => { if (off) close(); }, [off]);
  // a new label can change the width, so place it again
  useIsoLayoutEffect(() => { setAt(a => a && { ...a, x: 0, y: 0 }); }, [label, kbd]);
  // place it above the target, or below when there is no room (side="bottom" tries below first, for a target with a
  // header just above it), then fade it in
  useIsoLayoutEffect(() => {
    const t = tip.current; if (!at || !t || (at.x || at.y)) return;
    const w = t.offsetWidth, h = t.offsetHeight;
    const x = Math.max(8, Math.min(innerWidth - w - 8, at.r.left + at.r.width / 2 - w / 2));
    const up = at.r.top - h - 8, down = at.r.bottom + 8;
    const y = side === 'bottom' ? (down + h > innerHeight - 8 ? up : down) : (up < 8 ? down : up);
    setAt({ ...at, x, y }); requestAnimationFrame(() => setShow(true));
  }, [at]);

  const enterEl = (el: Element | null) => { over.current = true; if (!off) open(el); };
  const leave = () => { over.current = false; if (!forced) close(); };
  const focus = (el: Element) => { if (!off && el.matches(':focus-visible')) open(el, true); };
  const portal = at && typeof document !== 'undefined' && createPortal(
    <div ref={tip} className={cx('dm-tip', show && 'dm-show')} role="tooltip" data-dm="" style={{ left: at.x, top: at.y }}>{label}{kbd && <span className="dm-kbd">{kbd}</span>}</div>, document.body);

  if (isValidElement<Handlers>(children) && typeof children.type === 'string') {
    const own = children.props;
    return <>{cloneElement(children, {
      ref: (node: Element | null) => { target.current = node; setRef(own.ref, node); },
      onPointerEnter: (e: PointerEvent) => { own.onPointerEnter?.(e); enterEl(e.currentTarget as Element); },
      onPointerLeave: (e: PointerEvent) => { own.onPointerLeave?.(e); leave(); },
      onFocus: (e: FocusEvent) => { own.onFocus?.(e); focus(e.target as Element); },
      onBlur: (e: FocusEvent) => { own.onBlur?.(e); leave(); }
    })}{portal}</>;
  }
  return (
    <span ref={el => { target.current = el?.firstElementChild ?? null; }} style={{ display: 'contents' }}
      onPointerEnter={e => enterEl(e.currentTarget.firstElementChild)} onPointerLeave={leave}
      onFocus={e => focus(e.target)} onBlur={leave}>
      {children}{portal}
    </span>
  );
}

/** The ink for initials on an avatar colour: each of the eight avatar colours, 'var(--dm-av-b)' to 'var(--dm-av-t)', has its
    own (white, or a dark ink of its hue where white would fail contrast). Any other colour returns undefined, and the
    initials stay white */
export const avatarInk = (color: string) => /^var\(--dm-av-[a-z]\)$/.test(color) ? color.replace(')', '-ink)') : undefined;

/** A round avatar with initials, on a colour like 'var(--dm-av-l)' */
export const Avatar = ({ initials, color, size, className }: { initials: string; color: string; size?: number; className?: string }) => (
  <span className={cx('dm-av', className)} style={{ background: color, color: avatarInk(color), ...(size && { width: size, height: size }) }} aria-hidden="true">{initials}</span>
);

/* ---------- sources ---------- */
export type SourceKind = 'figma' | 'web' | 'ts' | 'tsx' | 'css' | 'csv' | 'pdf';
export interface Source { label: string; kind?: SourceKind; tip?: string; onClick?: () => void }
const FT: Partial<Record<SourceKind, string>> = { tsx: 'dm-re', csv: 'dm-csv', pdf: 'dm-pdf' };
/** A file or link chip, with its type in front */
export function SourceChip({ source, className, style, tipSide }: { source: Source; className?: string; style?: CSSProperties; tipSide?: 'top' | 'bottom' }) {
  const { label, kind, tip, onClick } = source;
  const mark = kind === 'figma' ? <Icon name="figma" size="xs" /> : kind === 'web' ? <Icon name="globe" size="xs" />
    : kind ? <span className={cx('dm-ft', FT[kind])}>{kind.toUpperCase()}</span> : null;
  const chip = <button type="button" className={cx('dm-fchip dm-lnk', className)} style={style} onClick={onClick}>{mark}{label}</button>;
  return tip ? <Tip label={tip} side={tipSide}>{chip}</Tip> : chip;
}

/** Plays the entrance animation, `delay` ms late, the first time it renders */
export const enter = (delay = 0): { className: string; style: CSSProperties } => ({ className: 'dm-enter', style: { animationDelay: delay + 'ms' } });

'use client';
import { useEffect, useRef, useState, type CSSProperties, type KeyboardEvent as ReactKeyboardEvent } from 'react';
import { cx } from './cx';
import { useControllable, useIsoLayoutEffect } from './hooks';

export interface PopoverOptions {
  /** Line the popover up with the trigger's start edge (the default) or its end edge */
  align?: 'start' | 'end';
  /** Open above or below the trigger. Left out, it opens below unless there is no room */
  side?: 'up' | 'down';
  /** Whether it is open. Leave it out to let the trigger toggle it */
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
}

/**
 * A menu or panel that opens from a button, placed the way designme.dev places them: under the trigger, or above it
 * when there is no room, and closed by a click outside, Escape or a resize. A menu (`role="menu"` or `"listbox"` on the pop)
 * works from the keyboard: Enter, Space or the down arrow opens it on its picked or first item, the up arrow on its last, the
 * arrows move and wrap, Home and End jump, Tab closes it, and closing gives the focus back to the trigger.
 *
 * Spread `trigger` on the button and `pop` on an element with the dm-pop class that is always rendered
 * (it fades in and out, so it needs to be there to measure). Its nearest positioned ancestor is what it is placed in.
 *
 *   const menu = usePopover({ align: 'end' });
 *   <button {...menu.trigger}>Model</button>
 *   <div {...menu.pop} className={cx(menu.pop.className, 'dm-my-menu')} role="menu">…</div>
 */
export function usePopover({ align = 'start', side, open, defaultOpen = false, onOpenChange }: PopoverOptions = {}) {
  const [isOpen, setOpen] = useControllable(open, defaultOpen, onOpenChange);
  const btn = useRef<HTMLButtonElement>(null);
  const pop = useRef<HTMLDivElement>(null);
  const [place, setPlace] = useState<CSSProperties>({});
  const set = useRef(setOpen);
  useEffect(() => { set.current = setOpen; });
  // where the focus goes as it opens: the picked item or the first ('first'), the last ('last'), or nowhere (null)
  const focusTo = useRef<'first' | 'last' | null>(null);
  // whether the focus was inside as it closed, so it goes back to the trigger rather than to the page
  const inside = useRef(false);

  useIsoLayoutEffect(() => {
    const b = btn.current, p = pop.current; if (!isOpen || !b || !p) return;
    const host = (p.offsetParent || p.parentElement) as HTMLElement;
    const hr = host.getBoundingClientRect(), br = b.getBoundingClientRect();
    const up = side === 'up' || (side !== 'down' && br.bottom + p.offsetHeight + 12 > innerHeight && br.top - p.offsetHeight > 12);
    let x = align === 'end' ? br.right - hr.left - p.offsetWidth : br.left - hr.left;
    x = Math.max(-hr.left + 8, Math.min(x, innerWidth - hr.left - p.offsetWidth - 8));
    setPlace({ left: x, top: up ? br.top - hr.top - p.offsetHeight - 6 : br.bottom - hr.top + 6, ['--dm-origin' as string]: `${up ? 'bottom' : 'top'} ${align === 'end' ? 'right' : 'left'}` });
  }, [isOpen, align, side]);

  // opened from the keyboard, a menu takes the focus; closed with the focus inside, the trigger gets it back
  useIsoLayoutEffect(() => {
    const p = pop.current;
    if (isOpen) {
      const to = focusTo.current; focusTo.current = null;
      if (to && p && isMenu(p)) {
        const it = menuItems(p), on = it.find(x => x.getAttribute('aria-checked') === 'true' || x.getAttribute('aria-selected') === 'true');
        (to === 'last' ? it[it.length - 1] : on || it[0])?.focus({ preventScroll: true });
      }
      return;
    }
    if (inside.current || (p && p.contains(document.activeElement))) { inside.current = false; btn.current?.focus({ preventScroll: true }); }
  }, [isOpen]);

  useEffect(() => {
    if (!isOpen) return;
    const down = (e: PointerEvent) => { const t = e.target as Node; if (!pop.current?.contains(t) && !btn.current?.contains(t)) set.current(false); };
    const key = (e: KeyboardEvent) => {
      const p = pop.current, t = e.target as HTMLElement;
      if (e.key === 'Escape') { set.current(false); btn.current?.focus(); return; }
      if (e.defaultPrevented || e.altKey || e.ctrlKey || e.metaKey || !p || !p.contains(t) || !isMenu(p)) return;
      // Tab moves on from the trigger and closes the menu
      if (e.key === 'Tab') { btn.current?.focus({ preventScroll: true }); inside.current = false; set.current(false); return; }
      // a field in a menu (a search, a web address) keeps its own keys
      if (/^(INPUT|TEXTAREA)$/.test(t.tagName) || t.isContentEditable) return;
      const to = step(menuItems(p), document.activeElement, e.key);
      if (to) { e.preventDefault(); to.focus({ preventScroll: true }); }
    };
    const track = (e: FocusEvent) => { inside.current = !!pop.current?.contains(e.target as Node); };
    // a real resize closes it; a page's own resize events (a layout settling) leave it open
    const resize = (e: UIEvent) => { if (e.isTrusted) set.current(false); };
    document.addEventListener('pointerdown', down); document.addEventListener('keydown', key); document.addEventListener('focusin', track); addEventListener('resize', resize);
    return () => { document.removeEventListener('pointerdown', down); document.removeEventListener('keydown', key); document.removeEventListener('focusin', track); removeEventListener('resize', resize); };
  }, [isOpen]);

  const close = () => setOpen(false);
  return {
    open: isOpen,
    setOpen,
    close,
    /** Closes a moment after a choice, so the pick shows before the menu fades, as on designme.dev */
    closeSoon: () => setTimeout(() => set.current(false), 120),
    /** Opens it with the focus on the picked item or the first ('first'), or on the last ('last'), as the keyboard does */
    openFocused: (where: 'first' | 'last' = 'first') => { focusTo.current = where; setOpen(true); },
    trigger: {
      ref: btn, 'aria-expanded': isOpen, 'aria-haspopup': 'menu' as const,
      /** Enter or Space (a click with no pointer) opens a menu with the focus on its picked item, or its first */
      onClick: (e?: { detail?: number }) => { if (!isOpen && e && e.detail === 0) focusTo.current = 'first'; setOpen(!isOpen); },
      /** The down and up arrows open a menu on its first or last item */
      onKeyDown: (e: ReactKeyboardEvent) => {
        if (e.key !== 'ArrowDown' && e.key !== 'ArrowUp') return;
        const p = pop.current; if (!p || !isMenu(p)) return;
        e.preventDefault();
        const where = e.key === 'ArrowUp' ? 'last' : 'first';
        if (isOpen) { const it = menuItems(p); (where === 'last' ? it[it.length - 1] : it[0])?.focus({ preventScroll: true }); }
        else { focusTo.current = where; setOpen(true); }
      }
    },
    pop: { ref: pop, className: cx('dm-pop', isOpen && 'dm-open'), style: place, inert: !isOpen }
  };
}

/* the keyboard in a popover menu, the WAI-ARIA menu button pattern: up and down move through the items and wrap at the ends
   (left and right too, in a grid like an emoji picker, where up and down move a row), and Home and End go to the first and
   last. A popover that is a dialog or a form leaves the keys to its component. Components with menus of their own use the
   same helpers */
export const isMenu = (p: HTMLElement) => /^(menu|listbox)$/.test(p.getAttribute('role') || '');
/** Puts the focus on a menu's picked item or its first ('first'), or on its last ('last') */
export function focusMenu(p: HTMLElement, where: 'first' | 'last' = 'first') {
  const it = menuItems(p), on = it.find(x => x.getAttribute('aria-checked') === 'true' || x.getAttribute('aria-selected') === 'true');
  (where === 'last' ? it[it.length - 1] : on || it[0])?.focus({ preventScroll: true });
}
/** The item an arrow key, Home or End moves to from the focused one, or null for any other key */
export const menuStep = (p: HTMLElement, key: string) => step(menuItems(p), document.activeElement, key);
const menuItems = (p: HTMLElement) => Array.from(p.querySelectorAll<HTMLElement>('button,[role^="menuitem"],[role="option"]'))
  .filter(el => !(el as HTMLButtonElement).disabled && el.getAttribute('aria-disabled') !== 'true' && el.getClientRects().length > 0 && !el.closest('[hidden]'));
function step(items: HTMLElement[], el: Element | null, key: string) {
  const n = items.length, i = items.indexOf(el as HTMLElement); if (!n) return null;
  if (key === 'Home') return items[0];
  if (key === 'End') return items[n - 1];
  const top = items[0].getBoundingClientRect().top, cols = items.filter(x => Math.abs(x.getBoundingClientRect().top - top) < 2).length, grid = cols > 1 && cols < n;
  const d = ({ ArrowDown: grid ? cols : 1, ArrowUp: grid ? -cols : -1, ArrowRight: grid || cols === n ? 1 : 0, ArrowLeft: grid || cols === n ? -1 : 0 } as Record<string, number>)[key];
  if (!d) return null;
  if (i < 0) return d > 0 ? items[0] : items[n - 1];
  return items[((i + d) % n + n) % n];
}

'use client';
import { useCallback, useEffect, useRef, type DependencyList, type RefObject } from 'react';

export interface Script {
  /** Resolves after `ms`, unless the component unmounts first, in which case the script simply stops */
  wait: (ms: number) => Promise<void>;
}

/** Runs a timed sequence of state changes, the way the demos on designme.dev play, and stops it on unmount */
export function useScript(run: (s: Script) => Promise<void>, deps: DependencyList = []) {
  useEffect(() => {
    let alive = true;
    const timers: ReturnType<typeof setTimeout>[] = [];
    const wait = (ms: number) => new Promise<void>(res => { timers.push(setTimeout(() => { if (alive) res(); }, ms)); });
    run({ wait }).catch(e => console.error(e));
    return () => { alive = false; timers.forEach(clearTimeout); };
  }, deps); // eslint-disable-line react-hooks/exhaustive-deps
}

/** Waits that a click handler can await, cleared when the component unmounts. For runs that start on a click rather than on mount */
export function useWait() {
  const timers = useRef(new Set<ReturnType<typeof setTimeout>>());
  useEffect(() => { const all = timers.current; return () => all.forEach(clearTimeout); }, []);
  return useCallback((ms: number) => new Promise<void>(res => { const t = setTimeout(() => { timers.current.delete(t); res(); }, ms); timers.current.add(t); }), []);
}

/* when the visitor last pressed a key or a pointer anywhere: a focus that comes with one (a Tab into the demo) is theirs,
   and a focus a script gives is not */
let lastInput = -1e9, listening = false;
function trackInput() {
  if (listening || typeof window === 'undefined') return;
  listening = true;
  const note = (e: Event) => { if (e.isTrusted) lastInput = e.timeStamp; };
  window.addEventListener('pointerdown', note, true); window.addEventListener('keydown', note, true);
}
/** Calls `take` at the visitor's first real click, key, typing or focus inside `el`, or a wheel a component there takes for itself. Returns a function that stops watching */
function watchTakeover(el: HTMLElement, take: () => void) {
  trackInput();
  const mine = (e: Event) => { if (e.isTrusted) take(); };
  const focus = (e: Event) => { if (e.isTrusted && e.timeStamp - lastInput < 100) take(); };
  const types = ['pointerdown', 'keydown', 'input', 'click'];
  // a wheel a component takes for itself (a canvas that pans with it) is the visitor's too; one that scrolls the page is not
  const wheel = (e: Event) => { if (e.isTrusted && e.defaultPrevented) take(); };
  types.forEach(t => el.addEventListener(t, mine, true)); el.addEventListener('focusin', focus, true); el.addEventListener('wheel', wheel, { passive: true });
  return () => { types.forEach(t => el.removeEventListener(t, mine, true)); el.removeEventListener('focusin', focus, true); el.removeEventListener('wheel', wheel); };
}

/** Whether the visitor has taken over the demo in `ref`, with their first real click, key, typing or focus inside it. A
    demo that also shows the agent at work checks it before each thing it does as the person in it, so those stop for good
    while the agent's own work, and anything the visitor starts, carries on. `onTake` runs at that moment */
export function useTakeover(ref: RefObject<HTMLElement | null>, onTake?: () => void) {
  const mine = useRef(false), take = useRef(onTake);
  take.current = onTake;
  useEffect(() => {
    const el = ref.current; if (!el) return;
    return watchTakeover(el, () => { if (mine.current) return; mine.current = true; take.current?.(); });
  }, [ref]);
  return useCallback(() => mine.current, []);
}

export interface Story extends Script {
  /** Clicks a control inside `ref`, the way the person in the story would */
  press: (selector: string) => void;
  /** Runs `fn` when the visitor takes over (at once if they already have), so the story can take back what it was halfway
      through, like the letters it had typed into a field */
  taken: (fn: () => void) => void;
}

/** A preview's story, or any demo that acts as the person in it: runs like useScript, once, but stops for good at the
    visitor's first click, key, typing or focus inside `ref`, so they take over from wherever it got to. While a mouse rests
    on `ref` the story holds where it is, so it never moves what the visitor is about to click, and carries on once it leaves */
export function useStory(ref: RefObject<HTMLElement | null>, run: (s: Story) => Promise<void>) {
  useEffect(() => {
    let alive = true, mine = false, held = false;
    const timers: ReturnType<typeof setTimeout>[] = [], undo: (() => void)[] = [], due: (() => void)[] = [];
    const el = ref.current;
    const stop = () => { alive = false; timers.forEach(clearTimeout); };
    const off = el ? watchTakeover(el, () => { if (mine) return; mine = true; stop(); undo.splice(0).forEach(f => f()); }) : () => {};
    const enter = (e: PointerEvent) => { if (e.pointerType === 'mouse') held = true; };
    const leave = () => { if (!held) return; held = false; due.splice(0).forEach(f => f()); };
    el?.addEventListener('pointerenter', enter); el?.addEventListener('pointerleave', leave);
    const wait = (ms: number) => new Promise<void>(res => { timers.push(setTimeout(() => { const go = () => { if (alive) res(); }; if (held && !mine) due.push(go); else go(); }, ms)); });
    const press = (selector: string) => { if (alive) el?.querySelector<HTMLElement>(selector)?.click(); };
    const taken = (fn: () => void) => { if (mine) fn(); else undo.push(fn); };
    run({ wait, press, taken }).catch(e => console.error(e));
    return () => { stop(); off(); el?.removeEventListener('pointerenter', enter); el?.removeEventListener('pointerleave', leave); };
  }, []); // eslint-disable-line react-hooks/exhaustive-deps
}

'use client';
import type { ReactNode, Ref } from 'react';

/** The component in the middle, its variant switch underneath, like the cards on designme.dev. `ref` reaches both, so a
    demo can tell when the visitor takes over (see useTakeover) */
export function Demo({ children, switcher, ref }: { children: ReactNode; switcher: ReactNode; ref?: Ref<HTMLDivElement> }) {
  return (
    <div ref={ref} style={{ width: '100%', minHeight: 260, display: 'flex', flexDirection: 'column', alignItems: 'center', gap: 32 }}>
      <div style={{ marginBlock: 'auto', width: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center' }}>{children}</div>
      <div data-dm="">{switcher}</div>
    </div>
  );
}
